// Deno suorittaa tämän tiedoston. Selain lähettää palvelimelle HTTP-pyynnön.
Deno.serve({ hostname: "127.0.0.1", port: 8000 }, (request: Request) => {
  const url = new URL(request.url);

  if (request.method !== "GET") {
    return new Response("Vain GET on sallittu.", {
      status: 405, headers: { Allow: "GET" },
    });
  }

  if (url.pathname === "/api/health") {
    return Response.json({ status: "ok", viesti: "Backend vastasi." });
  }

  if (url.pathname === "/") {
    return new Response("Hei! Palvelin toimii. Avaa /api/health.", {
      headers: { "content-type": "text/plain; charset=utf-8" },
    });
  }

  return Response.json({ error: "Osoitetta ei löydy." }, { status: 404 });
});
